-- Auth merge: Payroll IQ's auth.users rows win on email collision.
--
-- Measured 2026-09-16: 40 payroll-iq users, 9 target users, 7 colliding emails.
-- Payroll IQ wins because its uid is threaded through 19 FK columns, 3 jsonb
-- blobs and storage.objects.owner, while the target holds an auth uid in only
-- company_os.people.auth_user_id (4 rows set, 3 of them colliding) and
-- company_os.assistant_conversations.owner_auth_user_id (empty). One UPDATE,
-- against rewriting 24 columns for 7 people.
--
-- Password hashes copy with the row, so nobody is forced to reset. Sessions do
-- not copy: everyone signs in once more, which the project-ref change forces
-- anyway.

create schema if not exists migration_backup;

-- Reversibility, taken before anything is destroyed.
create table if not exists migration_backup.auth_users_pre_merge as select * from auth.users;
create table if not exists migration_backup.auth_identities_pre_merge as select * from auth.identities;
create table if not exists migration_backup.people_links_pre_merge as
  select id, auth_user_id, email from company_os.people where auth_user_id is not null;

-- Staging: Payroll IQ's rows land here first so the collision set is computed
-- from data, never from a hand-typed list of emails.
drop table if exists migration_backup.piq_users;
drop table if exists migration_backup.piq_identities;
create table migration_backup.piq_users as select * from auth.users with no data;
create table migration_backup.piq_identities as select * from auth.identities with no data;
