INSERT INTO migration_backup.piq_identities (provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at, id) VALUES ('63c94b2b-b85c-4dc2-99cd-4b4dc7e56ae1', '63c94b2b-b85c-4dc2-99cd-4b4dc7e56ae1', '{"sub": "63c94b2b-b85c-4dc2-99cd-4b4dc7e56ae1", "name": "Natali Simonovski", "email": "natali.simonovski@hotmail.com", "email_verified": false, "phone_verified": false}', 'email', '2026-09-02 02:21:52.649993+00', '2026-09-02 02:21:52.650038+00', '2026-09-02 02:21:52.650038+00', 'a7ef7474-d4a6-4f50-be13-63fbc22fc68b');
INSERT INTO migration_backup.piq_identities (provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at, id) VALUES ('c21e97ff-f49b-4f03-a584-56c3156c7748', 'c21e97ff-f49b-4f03-a584-56c3156c7748', '{"sub": "c21e97ff-f49b-4f03-a584-56c3156c7748", "name": "Louise", "email": "louisemissen06@gmail.com", "email_verified": false, "phone_verified": false}', 'email', '2026-09-08 23:01:11.139542+00', '2026-09-08 23:01:11.139595+00', '2026-09-08 23:01:11.139595+00', '30362054-963b-40e9-8817-aef85229fcbe');

-- 1. Release the FK: company_os.people.auth_user_id references auth.users with
--    no ON DELETE, so the delete below would be refused while these point at it.
update company_os.people p set auth_user_id = null
 where p.auth_user_id in (select t.id from auth.users t
   where lower(t.email) in (select lower(s.email) from migration_backup.piq_users s));

-- 2. Remove the target's rows for colliding emails ONLY. bj@ and quan@ do not
--    collide and are left alone.
delete from auth.identities i where i.user_id in (select t.id from auth.users t
   where lower(t.email) in (select lower(s.email) from migration_backup.piq_users s));
delete from auth.users t
 where lower(t.email) in (select lower(s.email) from migration_backup.piq_users s);

-- 3. Insert Payroll IQ's rows verbatim - uuid and encrypted_password preserved,
--    which is what makes sign-in seamless and why no reset email is needed.
--    Columns are enumerated from the catalogue rather than `select *`, because
--    auth.users.confirmed_at is a GENERATED column and Postgres refuses a
--    non-DEFAULT value for it. Reading the column list at run time also means a
--    future generated column cannot break this.
do $ins$
declare cols text;
begin
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into cols
    from information_schema.columns
   where table_schema='auth' and table_name='users' and is_generated = 'NEVER';
  execute format('insert into auth.users (%s) select %s from migration_backup.piq_users', cols, cols);

  select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into cols
    from information_schema.columns
   where table_schema='auth' and table_name='identities' and is_generated = 'NEVER';
  execute format('insert into auth.identities (%s) select %s from migration_backup.piq_identities', cols, cols);
end $ins$;

-- 4. Re-link people to the Payroll IQ uid, by email.
update company_os.people p set auth_user_id = u.id
  from auth.users u
 where p.auth_user_id is null and lower(p.email::text) = lower(u.email)
   and lower(u.email) in (select lower(s.email) from migration_backup.piq_users s);

-- 5. Post-conditions. A half-applied auth merge is far worse than a failed one.
do $$
declare orphans int; unlinked int; total int;
begin
  select count(*) into orphans from payroll_iq.users pu
    left join auth.users a on a.id = pu.id where a.id is null;
  if orphans <> 0 then raise exception 'payroll_iq.users with no auth row: %', orphans; end if;

  select count(*) into unlinked from company_os.people p
    left join auth.users a on a.id = p.auth_user_id
   where p.auth_user_id is not null and a.id is null;
  if unlinked <> 0 then raise exception 'people.auth_user_id pointing at nothing: %', unlinked; end if;

  select count(*) into total from auth.users;
  if total <> 42 then raise exception 'expected 42 auth users (40 piq + bj@ + quan@), got %', total; end if;
end $$;
